const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');

const root = path.resolve(__dirname, '../..');
const snapshot = require(path.join(root, 'app/refresh-status.json'));
const { dashboards } = require(path.join(root, 'api/config/dashboards.json'));

// Generated by: node tools/update-refresh-status.js
test('refresh-status.json has a timestamp and an entry for every dashboard dataset', () => {
  assert.ok(!Number.isNaN(Date.parse(snapshot.generatedAt)), 'generatedAt must be a date');
  const missing = [...new Set(dashboards.filter(d => d.datasetId).map(d => d.datasetId))]
    .filter(id => !snapshot.items[id]);
  assert.deepEqual(missing, [], 'run "node tools/update-refresh-status.js" after adding a dashboard');
});

test('refresh-status.json entries carry only the fields the portal reads', () => {
  const allowed = new Set(['status', 'refreshType', 'startTime', 'endTime', 'lastSuccessTime']);
  for (const [id, entry] of Object.entries(snapshot.items)) {
    assert.ok(typeof entry.status === 'string', `${id} needs a status`);
    for (const key of Object.keys(entry)) assert.ok(allowed.has(key), `${id}: unexpected field ${key}`);
  }
});
